const OWNER = "aurora-ui";
const ACTIVITY_WIDGET = "aurora-ui/activity";
const TICK_INTERVAL_MS = 100;
const THEME_PATH = fileURLToPath(
  new URL("../../themes/aurora-night.json", import.meta.url),
);
/**
 * Bursts of subagent events collapse into one status request. Nothing here
 * runs on a timer: the window only opens once an event has already arrived.
 */
const SUBAGENT_COALESCE_MS = 300;
const SUBAGENT_RPC_TIMEOUT_MS = 1_000;
const SUBAGENT_CONFIG_PATH = fileURLToPath(
  new URL("../subagent/config.json", import.meta.url),
);

/**
 * Once pi-subagents runs its Fleet Status Dock, that dock is the richer surface
 * for the same information: one line per agent with its concrete activity,
 * runtime and tokens, right below the editor. Aurora's activity widget hands
 * the subagent lines over instead of printing a second, poorer copy.
 *
 * Read from the subagent extension's own config rather than from a shared
 * setting: the dock is opt-in there, and only that file knows whether it is on.
 * Any read or parse problem means "no dock", i.e. the widget keeps reporting.
 * This runs once per session start, never from a render.
 */
function fleetDockOwnsSubagentDisplay(): boolean {
  try {
    const raw = JSON.parse(readFileSync(SUBAGENT_CONFIG_PATH, "utf8")) as {
      ui?: { fleetView?: unknown };
    };
    return raw.ui?.fleetView === true;
  } catch {
    return false;
  }
}

type SubagentToolArgs = {
  action?: unknown;
  async?: unknown;
  agent?: unknown;
  tasks?: unknown;
  chain?: unknown;
};

function record(value: unknown): Record<string, unknown> | undefined {
  return value && typeof value === "object" && !Array.isArray(value)
    ? (value as Record<string, unknown>)
    : undefined;
}

function agentNamesFromTaskList(value: unknown): string[] {
  if (!Array.isArray(value)) return [];
  return value.flatMap((item) => {
    const task = record(item);
    if (!task) return [];
    const agent = typeof task.agent === "string" ? task.agent : undefined;
    const parallel = agentNamesFromTaskList(task.parallel);
    return [...(agent ? [agent] : []), ...parallel];
  });
}

function foregroundSubagentsFromArgs(args: unknown): SubagentInfo[] {
  const input = args as SubagentToolArgs | undefined;
  if (!input || input.action !== undefined || input.async === true) return [];
  const agents = [
    ...(typeof input.agent === "string" ? [input.agent] : []),
    ...agentNamesFromTaskList(input.tasks),
    ...agentNamesFromTaskList(input.chain),
  ];
  return [...new Set(agents.length > 0 ? agents : ["subagent"])].map(
    (agent) => ({
      agent,
      status: "running",
    }),
  );
}

function textFromRpcReply(reply: unknown): string {
  const envelope = record(reply);
  const data = record(envelope?.data);
  // The RPC bridge serializes AgentToolResult text as data.text. Keep the
  // content-array fallback for the older bridge envelope.
  if (typeof data?.text === "string") return data.text;
  const content = data?.content;
  if (!Array.isArray(content)) return "";
  return content
    .flatMap((item) => {
      const part = record(item);
      return typeof part?.text === "string" ? [part.text] : [];
    })
    .join("\n");
}

function asyncSubagentsFromRpcReply(reply: unknown): SubagentInfo[] {
  const envelope = record(reply);
  if (!envelope || envelope.success !== true) return [];

  // This accepts the early structured bridge format too. The pinned bridge
  // serializes its AgentToolResult text through data.text.
  const data = record(envelope.data);
  if (Array.isArray(data?.runs)) {
    return data.runs.flatMap((item) => {
      const run = record(item);
      if (!run || typeof run.status !== "string") return [];
      const config = record(run.config);
      return [
        {
          agent: typeof config?.agent === "string" ? config.agent : "async",
          phase: typeof config?.phase === "string" ? config.phase : undefined,
          label: typeof config?.label === "string" ? config.label : undefined,
          status: run.status as SubagentInfo["status"],
        },
      ];
    });
  }

  const runs: SubagentInfo[] = [];
  const linePattern =
    /^-\s+([^|\s]+)\s+\|\s+(queued|running)\b[^|]*\|\s+(single|parallel|chain)\b/gm;
  for (const match of textFromRpcReply(reply).matchAll(linePattern)) {
    runs.push({
      agent: match[3] === "single" ? "async" : match[3]!,
      phase: match[1],
      status: match[2] as SubagentInfo["status"],
    });
  }
  return runs;
}

function makeEpoch(sequence: number): string {
  return `${Date.now().toString(36)}-${sequence.toString(36)}`;
}

function makeState(
  epoch: string,
  ctx: ExtensionContext,
  pi: ExtensionAPI,
): AuroraUiState {
  return {
    sessionEpoch: epoch,
    workflow: { phase: "work", label: "Work" },
    permissions: {},
    lsp: {},
    model: {
      id: ctx.model?.id,
      thinking: String(pi.getThinkingLevel()),
    },
    activity: { kind: "idle", activeTools: 0 },
  };
}

class AnimationTicker {
  private timer: ReturnType<typeof setInterval> | undefined;
  private tuiRefs = new Map<TUI, number>();
  private animationActive = false;
  private disposed = false;
  frame = 0;

  constructor(
    readonly motion: MotionMode,
    private readonly onFrame: (frame: number) => void,
  ) {}

  attach(tui: TUI): () => void {
    this.tuiRefs.set(tui, (this.tuiRefs.get(tui) ?? 0) + 1);
    let attached = true;
    return () => {
      if (!attached) return;
      attached = false;
      const count = this.tuiRefs.get(tui) ?? 0;
      if (count <= 1) this.tuiRefs.delete(tui);
      else this.tuiRefs.set(tui, count - 1);
    };
  }

  requestRender(): void {
    for (const tui of this.tuiRefs.keys()) tui.requestRender();
  }

  setAnimationActive(active: boolean): void {
    this.animationActive = active && this.motion === "contextual";
    if (this.animationActive && !this.timer && !this.disposed) {
      this.timer = setInterval(() => {
        this.frame = (this.frame + 1) % 10_000;
        this.onFrame(this.frame);
        this.requestRender();
      }, TICK_INTERVAL_MS);
    } else if (!this.animationActive && this.timer) {
      clearInterval(this.timer);
      this.timer = undefined;
    }
  }

  dispose(): void {
    this.disposed = true;
    this.animationActive = false;
    if (this.timer) clearInterval(this.timer);
    this.timer = undefined;
    this.tuiRefs.clear();
  }
}

function workingFrame(theme: Theme, motion: MotionMode, frame: number): string {
  if (motion === "off") return "";
  if (motion === "reduced") return theme.fg("accent", "●");
  const frames = ["·", "•", "●", "•"];
  const color = frame % frames.length === 2 ? "accent" : "muted";
  return theme.fg(color, frames[frame % frames.length]!);
}

export default function auroraUiExtension(pi: ExtensionAPI): void {
  let epochSequence = 0;
  let state: AuroraUiState | undefined;
  let ticker: AnimationTicker | undefined;
  let previousTheme: string | undefined;
  let selectedTheme: string | undefined;
  let activeContext: ExtensionContext | undefined;
  let activeSessionId: string | undefined;
  let disposed = true;
  let pendingRequestId: string | undefined;
  let busUnsubscribers: Array<() => void> = [];
  let subagentsCache: SubagentInfo[] = [];
  let asyncSubagentsCache: SubagentInfo[] = [];
  const foregroundSubagents = new Map<string, SubagentInfo[]>();
  let subagentsFetchInFlight: Promise<void> | undefined;
  let subagentsCoalesceTimer: ReturnType<typeof setTimeout> | undefined;
  /** An event arrived while a request was in flight; ask again once, after. */
  let subagentRefreshPending = false;
  /**
   * Bumped whenever a session ends. A reply carries the generation it was asked
   * under, so an answer that outlives its session cannot write into the next
   * one — the request itself is not cancellable, but its result is ignorable.
   */
  let subagentGeneration = 0;
  let fleetDockOwnsSubagents = false;
  let sessionCwd: string | undefined;
  let sessionHome: string | undefined;
  let showStartscreen = false;
  const activeTools = new Map<string, ActiveToolView>();

  /**
   * The transient surface above the editor has two presentation-only variants:
   * a fresh-session welcome and current live work. Both consume cached session
   * values only; rendering neither changes a workflow nor asks another system.
   */
  function renderActivityWidget(
    theme: Theme,
    width: number,
    rows: number,
  ): string[] {
    if (!state) return [];
    if (state.activity.kind === "idle") {
      if (!showStartscreen || !sessionCwd) return [];
      return renderStartscreen(theme, {
        width,
        rows,
        workflow: state.workflow.label,
        model: state.model.id,
        thinking: state.model.thinking,
        cwd: sessionCwd,
        homeDirectory: sessionHome,
      });
    }

    const layout = layoutForSize(width, rows);
    const compact = layout === "compact";
    const heading =
      state.activity.kind === "responding"
        ? theme.fg("accent", theme.bold("◉ RESPONDING"))
        : theme.fg(
            thinkingTone(state.model.thinking),
            theme.bold(`◉ THINKING  ${thinkingLabel(state.model.thinking)}`),
          );
    const contentWidth = Math.max(1, width - (compact ? 0 : 3));
    const tools = renderActiveTools(
      [...activeTools.values()],
      theme,
      contentWidth,
      Date.now(),
      { compact },
    );
    const subagents = fleetDockOwnsSubagents
      ? []
      : renderSubagents(subagentsCache, theme, contentWidth, { compact });
    if (compact) return [crop(heading, width), ...tools, ...subagents];
    if (tools.length === 0 && subagents.length === 0)
      return [crop(heading, width)];

    const rail = (glyph: "├─" | "╰─") => theme.fg("borderMuted", `${glyph} `);
    const toolRows = tools.map((line, index) =>
      `${rail(subagents.length > 0 || index < tools.length - 1 ? "├─" : "╰─")}${line}`,
    );
    const subagentRows =
      subagents.length === 0
        ? []
        : [`${rail("╰─")}${subagents[0]}`, ...subagents.slice(1)];
    return [crop(heading, width), theme.fg("borderMuted", "│"), ...toolRows, ...subagentRows];
  }

  function mergeSubagents(): void {
    const byKey = new Map<string, SubagentInfo>();
    for (const entry of [
      ...[...foregroundSubagents.values()].flat(),
      ...asyncSubagentsCache,
    ]) {
      byKey.set(
        `${entry.agent}\u0000${entry.phase ?? ""}\u0000${entry.label ?? ""}`,
        entry,
      );
    }
    subagentsCache = [...byKey.values()];
  }

  /** True while the answer to a request asked under `generation` still counts. */
  function subagentReplyStillWanted(generation: number): boolean {
    return !disposed && generation === subagentGeneration;
  }

  async function requestSubagentStatus(generation: number): Promise<void> {
    const requestId = crypto.randomUUID();
    // Subscribe before emitting, await after: a reply that arrives
    // synchronously must still find its listener.
    const reply = new Promise<unknown>((resolve) => {
      const unsubscribe = pi.events.on(
        `subagents:rpc:v1:reply:${requestId}`,
        (value: unknown) => {
          unsubscribe();
          resolve(value);
        },
      );
      setTimeout(() => {
        unsubscribe();
        resolve(null);
      }, SUBAGENT_RPC_TIMEOUT_MS);
    });
    pi.events.emit("subagents:rpc:v1:request", {
      version: 1,
      requestId,
      method: "status",
      params: {},
    });
    const value = await reply;
    if (!subagentReplyStillWanted(generation)) return;
    asyncSubagentsCache = asyncSubagentsFromRpcReply(value);
  }

  /**
   * Async subagent runs are only knowable by asking the subagent package, and
   * this is the one place that asks. It is reached from the subagent event
   * handler alone — never from a render — so the cost is bounded by how often
   * subagents actually change state, not by the frame rate. A burst of events
   * collapses into a single request.
   *
   * An event that arrives while a request is already in flight would otherwise
   * be lost, leaving the cache stale for as long as nothing else happens. It
   * sets a single pending flag instead, so any number of such events produce
   * exactly one follow-up request once the current one has answered.
   */
  function refreshSubagents(): void {
    if (fleetDockOwnsSubagents || disposed) return;
    if (subagentsFetchInFlight) {
      subagentRefreshPending = true;
      return;
    }
    if (subagentsCoalesceTimer) return;
    subagentsCoalesceTimer = setTimeout(() => {
      subagentsCoalesceTimer = undefined;
      if (disposed) return;
      if (subagentsFetchInFlight) {
        subagentRefreshPending = true;
        return;
      }
      const generation = subagentGeneration;
      subagentsFetchInFlight = requestSubagentStatus(generation)
        .catch(() => {
          if (subagentReplyStillWanted(generation)) asyncSubagentsCache = [];
        })
        .finally(() => {
          // A stale request touches nothing at all — not even the in-flight
          // gate, which by now may belong to the session that replaced it.
          if (!subagentReplyStillWanted(generation)) return;
          subagentsFetchInFlight = undefined;
          mergeSubagents();
          ticker?.requestRender();
          if (!subagentRefreshPending) return;
          subagentRefreshPending = false;
          refreshSubagents();
        });
    }, SUBAGENT_COALESCE_MS);
  }

  /** Foreground runs are known from the tool call itself; no request needed. */
  function refreshForegroundSubagents(): void {
    mergeSubagents();
    ticker?.requestRender();
  }

  function applyWorking(ctx: ExtensionContext): void {
    if (!state || !ticker) return;
    const active = state.activity.kind !== "idle";
    ticker.setAnimationActive(active);

    // Aurora's activity widget is the single live-work surface. Keeping Pi's
    // native indicator visible as well creates a second moving signal next to
    // the editor; motion is rendered by the widget itself when enabled.
    ctx.ui.setWorkingVisible(false);
  }

  function updateState(ctx: ExtensionContext, patch: AuroraUiStatePatch): void {
    if (
      !state ||
      disposed ||
      ctx.sessionManager.getSessionId() !== activeSessionId
    )
      return;
    mergeAuroraUiState(state, patch);
    ticker?.requestRender();
    if (patch.activity) applyWorking(ctx);
  }

  function emitSnapshot(request: AuroraUiStateRequest): void {
    if (!state || request.sessionEpoch !== state.sessionEpoch) return;
    const event: AuroraUiSnapshotEvent = {
      type: "snapshot",
      requestId: request.requestId,
      sessionEpoch: state.sessionEpoch,
      source: OWNER,
      state: {
        workflow: { ...state.workflow },
        permissions: { ...state.permissions },
        lsp: { ...state.lsp },
        model: { ...state.model },
        activity: { ...state.activity },
      },
    };
    pi.events.emit(AURORA_UI_CHANNELS.snapshot, event);
  }

  function installBus(ctx: ExtensionContext): void {
    if (!state) return;
    busUnsubscribers = [
      pi.events.on(AURORA_UI_CHANNELS.request, (value) => {
        if (!isAuroraUiStateRequest(value) || value.requester === OWNER) return;
        emitSnapshot(value);
      }),
      pi.events.on(AURORA_UI_CHANNELS.patch, (value) => {
        if (
          !state ||
          !isAuroraUiPatchEvent(value) ||
          value.sessionEpoch !== state.sessionEpoch
        )
          return;
        updateState(ctx, value.patch);
      }),
      pi.events.on(AURORA_UI_CHANNELS.snapshot, (value) => {
        if (
          !state ||
          !pendingRequestId ||
          !isAuroraUiSnapshotEvent(value) ||
          value.requestId !== pendingRequestId ||
          value.sessionEpoch !== state.sessionEpoch
        )
          return;
        updateState(ctx, value.state);
      }),
      // The one trigger for an async subagent status request. It lives with
      // the session rather than with a component, so the request cannot be
      // tied to how often anything happens to repaint.
      pi.events.on("subagent:control-event", () => refreshSubagents()),
    ];

    pendingRequestId = `${state.sessionEpoch}:${OWNER}`;
    pi.events.emit(AURORA_UI_CHANNELS.request, {
      type: "request",
      requestId: pendingRequestId,
      sessionEpoch: state.sessionEpoch,
      requester: OWNER,
    } satisfies AuroraUiStateRequest);
  }

  function disposeSession(ctx?: ExtensionContext): void {
    if (disposed) return;
    disposed = true;
    for (const unsubscribe of busUnsubscribers.splice(0)) unsubscribe();
    pendingRequestId = undefined;
    activeTools.clear();
    foregroundSubagents.clear();
    subagentsCache = [];
    asyncSubagentsCache = [];
    // A request already on the wire cannot be recalled, so retire the
    // generation it was asked under: whenever it answers, it answers for a
    // session that no longer exists and is dropped instead of applied.
    subagentGeneration += 1;
    subagentRefreshPending = false;
    subagentsFetchInFlight = undefined;
    if (subagentsCoalesceTimer) clearTimeout(subagentsCoalesceTimer);
    subagentsCoalesceTimer = undefined;
    ticker?.dispose();
    ticker = undefined;

    const uiContext = ctx ?? activeContext;
    if (uiContext?.mode === "tui" && uiContext.hasUI) {
      uiContext.ui.setFooter(undefined);
      uiContext.ui.setWidget(ACTIVITY_WIDGET, undefined);
      uiContext.ui.setWorkingVisible(false);
      uiContext.ui.setWorkingMessage();
      uiContext.ui.setWorkingIndicator();
      if (
        previousTheme &&
        selectedTheme &&
        uiContext.ui.theme.name === selectedTheme &&
        previousTheme !== selectedTheme
      ) {
        uiContext.ui.setTheme(previousTheme);
      }
    }
    state = undefined;
    sessionCwd = undefined;
    sessionHome = undefined;
    showStartscreen = false;
    activeContext = undefined;
    activeSessionId = undefined;
    previousTheme = undefined;
    selectedTheme = undefined;
  }

  pi.on("resources_discover", () => ({ themePaths: [THEME_PATH] }));

  pi.on("session_start", (_event, ctx) => {
    disposeSession(activeContext);
    if (ctx.mode !== "tui" || !ctx.hasUI) return;

    const loaded = loadSetupConfig(ctx.cwd, ctx.isProjectTrusted());
    fleetDockOwnsSubagents = fleetDockOwnsSubagentDisplay();
    sessionCwd = ctx.cwd;
    sessionHome = homedir();
    showStartscreen = !ctx.sessionManager
      .getEntries()
      .some((entry: { type?: string }) => entry.type === "message");
    const epoch = makeEpoch(++epochSequence);
    state = makeState(epoch, ctx, pi);
    // The permission label is deliberately left empty: it means the permission
    // mode, and only `permissions/session-state.ts` knows it. That extension
    // answers the state request emitted by `installBus` below, still inside
    // this handler. Seeding it from `permissions.bash` — a different setting
    // entirely — is what used to put the bash policy under a mode label.
    state.lsp.state = loaded.config.lsp.enabled ? "leerlauf" : "aus";
    activeContext = ctx;
    activeSessionId = ctx.sessionManager.getSessionId();
    disposed = false;

    previousTheme = ctx.ui.theme.name;
    selectedTheme = loaded.config.ui.theme;
    const themeResult = ctx.ui.setTheme(selectedTheme);
    if (!themeResult.success) {
      ctx.ui.notify(
        `Aurora theme: ${themeResult.error ?? "nicht verfügbar"}`,
        "warning",
      );
    }

    ticker = new AnimationTicker(loaded.config.ui.motion, () => {});

    const sessionCtx = ctx;
    ctx.ui.setFooter((tui, theme, footerData) => {
      const detachTicker = ticker!.attach(tui);
      // The footer reports the context share, which moves as the branch grows.
      // The subscription exists to schedule a repaint, not to read anything:
      // a value that only changes on an event is only redrawn on that event.
      const unsubscribeBranch = footerData.onBranchChange(() =>
        tui.requestRender(),
      );

      return {
        invalidate() {},
        dispose() {
          unsubscribeBranch();
          detachTicker();
        },
        render(width: number): string[] {
          if (!state) return [];
          return renderFooterLines(theme, width, {
            state,
            statuses: footerData.getExtensionStatuses(),
            contextPercent: sessionCtx.getContextUsage()?.percent ?? null,
            cwd: sessionCwd,
            homeDirectory: sessionHome,
          });
        },
      };
    });

    ctx.ui.setWidget(
      ACTIVITY_WIDGET,
      (tui, theme) => {
        const detachTicker = ticker!.attach(tui);
        return {
          invalidate() {},
          dispose: detachTicker,
          render: (width: number) =>
            renderActivityWidget(
              theme,
              width,
              (tui as unknown as { terminal?: { rows?: number } }).terminal
                ?.rows ?? 24,
            ),
        };
      },
      { placement: "aboveEditor" },
    );
    ctx.ui.setWorkingVisible(false);
    ctx.ui.setWorkingIndicator(
      loaded.config.ui.motion === "off"
        ? { frames: [] }
        : {
            frames: [workingFrame(ctx.ui.theme, loaded.config.ui.motion, 0)],
          },
    );
    installBus(ctx);
  });

  pi.on("before_agent_start", () => {
    showStartscreen = false;
    ticker?.requestRender();
  });

  pi.on("agent_start", (_event, ctx) => {
    showStartscreen = false;
    activeTools.clear();
    foregroundSubagents.clear();
    refreshForegroundSubagents();
    updateState(ctx, {
      activity: {
        kind: "thinking",
        // The real configured depth, never a guess: this is the only place
        // thinking is visible while `hideThinkingBlock` is set.
        label: `Thinking · ${pi.getThinkingLevel()}`,
        activeTools: 0,
      },
    });
  });

  pi.on("tool_execution_start", (event, ctx) => {
    activeTools.set(event.toolCallId, {
      id: event.toolCallId,
      name: event.toolName,
      target: compactToolTarget(event.toolName, event.args),
      startedAt: Date.now(),
    });
    if (event.toolName === "subagent") {
      const subagents = foregroundSubagentsFromArgs(event.args);
      if (subagents.length > 0)
        foregroundSubagents.set(event.toolCallId, subagents);
      refreshForegroundSubagents();
      refreshSubagents();
    }
    updateState(ctx, {
      activity: {
        kind: "tool",
        label: `${activeTools.size} Tool${activeTools.size === 1 ? "" : "s"} aktiv`,
        activeTools: activeTools.size,
      },
    });
  });

  pi.on("tool_execution_end", (event, ctx) => {
    activeTools.delete(event.toolCallId);
    if (event.toolName === "subagent") {
      foregroundSubagents.delete(event.toolCallId);
      refreshForegroundSubagents();
      refreshSubagents();
    }
    updateState(ctx, {
      activity:
        activeTools.size > 0
          ? {
              kind: "tool",
              label: `${activeTools.size} Tool${activeTools.size === 1 ? "" : "s"} aktiv`,
              activeTools: activeTools.size,
            }
          : {
              kind: "responding",
              label: undefined,
              activeTools: 0,
            },
    });
  });

  pi.on("message_update", (event, ctx) => {
    if (!event.assistantMessageEvent.type.startsWith("text_")) return;
    activeTools.clear();
    foregroundSubagents.clear();
    refreshForegroundSubagents();
    updateState(ctx, {
      activity: { kind: "idle", label: undefined, activeTools: 0 },
    });
  });

  pi.on("model_select", (event, ctx) => {
    updateState(ctx, { model: { id: event.model.id } });
  });

  pi.on("thinking_level_select", (event, ctx) => {
    updateState(ctx, { model: { thinking: String(event.level) } });
  });

  const settle = (_event: unknown, ctx: ExtensionContext) => {
    activeTools.clear();
    foregroundSubagents.clear();
    refreshForegroundSubagents();
    updateState(ctx, {
      activity: { kind: "idle", label: undefined, activeTools: 0 },
    });
  };
  pi.on("agent_end", settle);
  pi.on("agent_settled", settle);
  pi.on("session_shutdown", (_event, ctx) => disposeSession(ctx));
}

import type { Theme } from "@earendil-works/pi-coding-agent";
import { truncateToWidth } from "@earendil-works/pi-tui";
import { footerTier } from "../shared/layout.ts";

/** The compact running marker shared by tool rows. */
export const RUNNING_GLYPH = "◌";

export interface ActiveToolView {
  id: string;
  name: string;
  target?: string;
  startedAt: number;
}

/**
 * A subagent the current turn started. Aurora keeps no state machine of its
 * own for these: foreground runs come straight off the `subagent` tool call,
 * async runs off the status reply the subagent package already publishes.
 */
export interface SubagentInfo {
  agent: string;
  phase?: string;
  label?: string;
  status: "running" | "paused" | "needs_attention" | "queued";
}

interface ToolPresentation {
  glyph: string;
  label: string;
}

const TOOL_PRESENTATIONS: Record<string, ToolPresentation> = {
  read: { glyph: "◌", label: "Read" },
  grep: { glyph: "⌕", label: "Grep" },
  rg: { glyph: "⌕", label: "Grep" },
  bash: { glyph: "›", label: "Bash" },
  edit: { glyph: "✎", label: "Edit" },
  write: { glyph: "✎", label: "Edit" },
  subagent: { glyph: "◇", label: "Agent" },
};

function firstString(
  args: unknown,
  candidates: readonly string[],
): string | undefined {
  if (!args || typeof args !== "object") return undefined;
  const values = args as Record<string, unknown>;
  for (const key of candidates) {
    const value = values[key];
    if (typeof value === "string" && value.trim()) return value.trim();
  }
  return undefined;
}

export function compactToolTarget(
  toolName: string,
  args: unknown,
): string | undefined {
  const target = firstString(args, [
    "path",
    "file_path",
    "file",
    "query",
    "pattern",
    "command",
    "url",
    "symbol",
    "name",
    "role",
    "task",
    "target",
  ]);
  if (!target) return undefined;
  if (toolName === "bash") return target.replace(/\s+/g, " ");
  return target;
}

export function toolPresentation(name: string): ToolPresentation {
  return (
    TOOL_PRESENTATIONS[name.toLowerCase()] ?? {
      glyph: RUNNING_GLYPH,
      label: name || "Tool",
    }
  );
}

/**
 * Renders lifecycle metadata only. Aurora deliberately does not re-register or
 * wrap tools, so argument validation, execution, cancellation, updates and
 * results continue to be handled exactly by Pi's core tool definitions.
 */
export function renderActiveTools(
  tools: readonly ActiveToolView[],
  theme: Theme,
  width: number,
  now: number,
  options: { compact?: boolean } = {},
): string[] {
  const available = Math.max(1, width);
  const compact = options.compact ?? footerTier(width) === "compact";
  const limit = compact ? 1 : 3;
  const visible = tools.slice(0, limit).map((tool) => {
    const elapsed = Math.max(0, Math.floor((now - tool.startedAt) / 1000));
    const presentation = toolPresentation(tool.name);
    const target = tool.target ? `  ${theme.fg("muted", tool.target)}` : "";
    const marker = theme.fg("accent", presentation.glyph);
    const line = `${marker} ${theme.bold(presentation.label)}${target} ${theme.fg("dim", `${elapsed}s`)}`;
    return truncateToWidth(line, available, "…");
  });
  const hidden = tools.length - visible.length;
  if (hidden > 0)
    visible.push(
      truncateToWidth(
        theme.fg("muted", `↳ +${hidden} weitere Tools`),
        available,
        "…",
      ),
    );
  return visible;
}

function subagentTone(
  status: SubagentInfo["status"],
): "success" | "warning" | "error" | "muted" {
  switch (status) {
    case "running":
      return "success";
    case "paused":
      return "warning";
    case "needs_attention":
      return "error";
    case "queued":
      return "muted";
  }
}

function subagentGlyph(status: SubagentInfo["status"]): string {
  switch (status) {
    case "running":
      return "◉";
    case "queued":
      return "○";
    case "paused":
      return "◌";
    case "needs_attention":
      return "!";
  }
}

/**
 * Subagents appear inline with the work that started them, for as long as that
 * work runs — no permanent tab strip, no navigation level of their own. When
 * the turn settles the widget goes away with everything else in it.
 */
export function renderSubagents(
  subagents: readonly SubagentInfo[],
  theme: Theme,
  width: number,
  options: { compact?: boolean } = {},
): string[] {
  if (subagents.length === 0) return [];
  const available = Math.max(1, width);
  const compact = options.compact ?? footerTier(width) === "compact";
  const clip = (value: string) => truncateToWidth(value, available, "…");
  const attention = subagents.filter(
    (entry) => entry.status === "needs_attention",
  ).length;
  const summary = clip(
    compact
      ? `${theme.fg("muted", "▾")} ${theme.fg("text", `Subagents · ${subagents.length} aktiv`)}`
      : theme.bold(theme.fg("border", `SUBAGENTS  ${subagents.length} aktiv`)),
  );
  const attentionLine = attention
    ? theme.fg("error", ` · ${attention} Aufmerksamkeit`)
    : "";
  const summaryWithAttention = clip(`${summary}${attentionLine}`);
  if (compact) return [summaryWithAttention];

  // Whatever needs a decision is worth the few lines this surface has.
  const ordered = [...subagents].sort(
    (a, b) =>
      Number(b.status === "needs_attention") -
      Number(a.status === "needs_attention"),
  );
  const visible = ordered.slice(0, 3);
  const lines = visible.flatMap((entry) => {
    const glyph = theme.fg(subagentTone(entry.status), subagentGlyph(entry.status));
    const rows = [clip(`   ${glyph} ${theme.bold(entry.agent)}`)];
    const detail = entry.phase ?? entry.label;
    if (detail) rows.push(clip(`     ${theme.fg("muted", `↳ ${detail}`)}`));
    return rows;
  });
  const hidden = subagents.length - visible.length;
  if (hidden > 0)
    lines.push(clip(`   ${theme.fg("muted", `↳ +${hidden} weitere`)}`));
  return [summaryWithAttention, ...lines];
}

import type { EventBus, ExtensionAPI } from "@earendil-works/pi-coding-agent";
import { WORKFLOW_MODES, type WorkflowMode } from "../shared/workflow-mode.ts";

export const AURORA_UI_CHANNELS = {
  request: "aurora-ui/state/request",
  patch: "aurora-ui/state/patch",
  snapshot: "aurora-ui/state/snapshot",
} as const;

/** Presentation mirror of the selected workflow mode. */
export type AuroraWorkflowPhase = WorkflowMode;

export type AuroraActivityKind = "idle" | "thinking" | "tool" | "responding";

export interface AuroraUiState {
  sessionEpoch: string;
  workflow: {
    phase: AuroraWorkflowPhase;
    label: string;
  };
  permissions: {
    level?: string;
    label?: string;
  };
  lsp: {
    state?: string;
    detail?: string;
  };
  model: {
    id?: string;
    thinking?: string;
  };
  activity: {
    kind: AuroraActivityKind;
    label?: string;
    activeTools: number;
  };
}

export interface AuroraUiStatePatch {
  workflow?: Partial<AuroraUiState["workflow"]>;
  permissions?: Partial<AuroraUiState["permissions"]>;
  lsp?: Partial<AuroraUiState["lsp"]>;
  model?: Partial<AuroraUiState["model"]>;
  activity?: Partial<AuroraUiState["activity"]>;
}

export interface AuroraUiStateRequest {
  type: "request";
  requestId: string;
  sessionEpoch: string;
  requester: string;
}

export interface AuroraUiPatchEvent {
  type: "patch";
  sessionEpoch: string;
  source: string;
  patch: AuroraUiStatePatch;
}

export interface AuroraUiSnapshotEvent {
  type: "snapshot";
  requestId: string;
  sessionEpoch: string;
  source: string;
  state: AuroraUiStatePatch;
}

function emit(bus: EventBus, channel: string, value: unknown): void {
  bus.emit(channel, value);
}

/** Publish a state patch only for the epoch obtained from a state request. */
export function publishAuroraUiPatch(
  pi: Pick<ExtensionAPI, "events">,
  sessionEpoch: string,
  source: string,
  patch: AuroraUiStatePatch,
): void {
  emit(pi.events, AURORA_UI_CHANNELS.patch, {
    type: "patch",
    sessionEpoch,
    source,
    patch,
  } satisfies AuroraUiPatchEvent);
}

/** Answer a request with the provider's complete view of its owned fields. */
export function publishAuroraUiSnapshot(
  pi: Pick<ExtensionAPI, "events">,
  request: AuroraUiStateRequest,
  source: string,
  state: AuroraUiStatePatch,
): void {
  emit(pi.events, AURORA_UI_CHANNELS.snapshot, {
    type: "snapshot",
    requestId: request.requestId,
    sessionEpoch: request.sessionEpoch,
    source,
    state,
  } satisfies AuroraUiSnapshotEvent);
}

export function isAuroraUiStateRequest(
  value: unknown,
): value is AuroraUiStateRequest {
  if (!value || typeof value !== "object") return false;
  const event = value as Partial<AuroraUiStateRequest>;
  return (
    event.type === "request" &&
    typeof event.requestId === "string" &&
    typeof event.sessionEpoch === "string" &&
    typeof event.requester === "string"
  );
}

export function isAuroraUiPatchEvent(
  value: unknown,
): value is AuroraUiPatchEvent {
  if (!value || typeof value !== "object") return false;
  const event = value as Partial<AuroraUiPatchEvent>;
  return (
    event.type === "patch" &&
    typeof event.sessionEpoch === "string" &&
    typeof event.source === "string" &&
    Boolean(event.patch) &&
    typeof event.patch === "object"
  );
}

export function isAuroraUiSnapshotEvent(
  value: unknown,
): value is AuroraUiSnapshotEvent {
  if (!value || typeof value !== "object") return false;
  const event = value as Partial<AuroraUiSnapshotEvent>;
  return (
    event.type === "snapshot" &&
    typeof event.requestId === "string" &&
    typeof event.sessionEpoch === "string" &&
    typeof event.source === "string" &&
    Boolean(event.state) &&
    typeof event.state === "object"
  );
}

export function mergeAuroraUiState(
  state: AuroraUiState,
  patch: AuroraUiStatePatch,
): void {
  const workflowPhases: readonly AuroraWorkflowPhase[] = WORKFLOW_MODES;
  const activityKinds: readonly AuroraActivityKind[] = [
    "idle",
    "thinking",
    "tool",
    "responding",
  ];

  if (patch.workflow) {
    if (patch.workflow.phase && workflowPhases.includes(patch.workflow.phase))
      state.workflow.phase = patch.workflow.phase;
    if (typeof patch.workflow.label === "string")
      state.workflow.label = patch.workflow.label;
  }
  if (patch.permissions) {
    if ("level" in patch.permissions)
      state.permissions.level =
        typeof patch.permissions.level === "string"
          ? patch.permissions.level
          : undefined;
    if ("label" in patch.permissions)
      state.permissions.label =
        typeof patch.permissions.label === "string"
          ? patch.permissions.label
          : undefined;
  }
  if (patch.lsp) {
    if ("state" in patch.lsp)
      state.lsp.state =
        typeof patch.lsp.state === "string" ? patch.lsp.state : undefined;
    if ("detail" in patch.lsp)
      state.lsp.detail =
        typeof patch.lsp.detail === "string" ? patch.lsp.detail : undefined;
  }
  if (patch.model) {
    if ("id" in patch.model)
      state.model.id =
        typeof patch.model.id === "string" ? patch.model.id : undefined;
    if ("thinking" in patch.model)
      state.model.thinking =
        typeof patch.model.thinking === "string"
          ? patch.model.thinking
          : undefined;
  }
  if (patch.activity) {
    if (patch.activity.kind && activityKinds.includes(patch.activity.kind))
      state.activity.kind = patch.activity.kind;
    if ("label" in patch.activity)
      state.activity.label =
        typeof patch.activity.label === "string"
          ? patch.activity.label
          : undefined;
    if (typeof patch.activity.activeTools === "number")
      state.activity.activeTools = Math.max(
        0,
        Math.floor(patch.activity.activeTools),
      );
  }
}

import type { Theme } from "@earendil-works/pi-coding-agent";
import { visibleWidth } from "@earendil-works/pi-tui";
import { footerTier, type Layout } from "../shared/layout.ts";
import {
  renderSegment,
  STATUS_SEPARATOR,
  statusSeparator,
  type Tone,
} from "../shared/ui-theme.ts";
import { compactCwd } from "./cwd.ts";
import { crop } from "./layout.ts";
import type { AuroraUiState } from "./state.ts";
import { thinkingTone } from "./thinking.ts";

/**
 * The footer is the one permanent status surface, and it is one line.
 *
 * Everything it reports comes out of runtime state that some other extension
 * already publishes on the Aurora bus or through `getExtensionStatuses()`.
 * Nothing here starts a process, probes git or the LSP, asks a provider or
 * touches the file system: `render` is called on every frame, so any of that
 * would be paid for continuously and for nothing.
 */
export interface FooterInput {
  state: AuroraUiState;
  statuses: ReadonlyMap<string, string>;
  contextPercent: number | null;
  /** Captured from ExtensionContext at session start; never read from render I/O. */
  cwd?: string;
  homeDirectory?: string;
}

const CONTEXT_WARNING_PERCENT = 70;
const CONTEXT_CRITICAL_PERCENT = 90;
const MODEL_MAX_COLUMNS = 32;
const FOLDER_MAX_COLUMNS: Record<Layout, number> = {
  wide: 34,
  comfortable: 24,
  standard: 18,
  compact: 12,
};

/**
 * Where a segment sits on the line. Reading order is fixed and independent of
 * how hard the segment fights to stay: risk is loud, but it belongs at the end
 * where a scan finishes, not wedged between the model and the thinking level.
 * A plain object rather than a `const enum` — the test loader transpiles
 * without type information.
 */
const Slot = {
  workflow: 0,
  model: 1,
  thinking: 2,
  folder: 3,
  context: 4,
  verification: 5,
  risk: 6,
} as const;

type Slot = (typeof Slot)[keyof typeof Slot];

/**
 * What gets dropped first when the line is too long — lowest survives longest.
 * The workflow is last man standing. Everything that reports an actual problem
 * outranks the model name: at the widths where this matters the user knows
 * which model they picked, and does not yet know their language server died.
 */
const Priority = {
  workflow: 0,
  yolo: 1,
  failedVerification: 2,
  exhaustedContext: 3,
  lsp: 4,
  folder: 5,
  model: 6,
  verification: 7,
  thinking: 8,
  context: 9,
} as const;

type Priority = (typeof Priority)[keyof typeof Priority];

interface Segment {
  slot: Slot;
  priority: Priority;
  text: string;
  tone: Tone;
  bold?: boolean;
  /**
   * A segment that reports a risk or a failure. It ignores the width tier,
   * because a footer that hides YOLO or a failed verification to save four
   * columns is worse than one that has to drop something else.
   */
  critical?: boolean;
}

/** Which routine segments each width tier may show at all. */
const ROUTINE_TIERS: Record<Layout, ReadonlySet<Slot>> = {
  wide: new Set([
    Slot.workflow,
    Slot.model,
    Slot.thinking,
    Slot.folder,
    Slot.context,
    Slot.verification,
  ]),
  comfortable: new Set([
    Slot.workflow,
    Slot.model,
    Slot.thinking,
    Slot.folder,
    Slot.verification,
  ]),
  standard: new Set([Slot.workflow, Slot.model, Slot.folder]),
  compact: new Set([Slot.workflow, Slot.model, Slot.folder]),
};

function verificationState(input: FooterInput): string | null {
  const value = input.statuses.get("verification");
  return value ? value.replace(/^Verify:\s*/, "") : null;
}

function verificationTone(state: string): Tone {
  if (state === "verified") return "success";
  if (state === "clean") return "muted";
  if (state === "checks_failed") return "error";
  return "warning";
}

/** Only an unproven or failing workspace is worth defending space for. */
function verificationNeedsAttention(state: string | null): boolean {
  return state !== null && state !== "clean" && state !== "verified";
}

function lspState(input: FooterInput): string {
  return input.statuses.get("lsp") ?? input.state.lsp.state ?? "—";
}

/**
 * A working, idle or disabled language server is not news, so it stays off the
 * line entirely. Only a degraded one is, and it claims space at any width.
 *
 * `extensions/lsp/status.ts` publishes a closed set: `aus`, `leerlauf`,
 * `eingeschränkt` and `${n} aktiv`. Matching the one bad value is what keeps
 * `3 aktiv` — a perfectly healthy server count — out of the warning slot.
 */
function lspNeedsAttention(state: string): boolean {
  return state === "eingeschränkt";
}

function collectSegments(input: FooterInput, width: number): Segment[] {
  const tier = footerTier(width);
  const segments: Segment[] = [
    {
      slot: Slot.workflow,
      priority: Priority.workflow,
      text: input.state.workflow.label,
      tone: "accent",
      bold: true,
    },
    {
      slot: Slot.model,
      priority: Priority.model,
      // The real runtime model id. Prettifying it into a marketing name would
      // mean inventing a mapping the runtime never gave us.
      text: crop(input.state.model.id ?? "kein Modell", MODEL_MAX_COLUMNS),
      tone: "text",
    },
  ];

  if (input.state.model.thinking) {
    segments.push({
      slot: Slot.thinking,
      priority: Priority.thinking,
      text: input.state.model.thinking.toUpperCase(),
      tone: thinkingTone(input.state.model.thinking),
      bold: true,
    });
  }

  if (input.cwd) {
    segments.push({
      slot: Slot.folder,
      priority: Priority.folder,
      text: compactCwd(input.cwd, FOLDER_MAX_COLUMNS[tier], input.homeDirectory),
      tone: "muted",
    });
  }

  if (input.contextPercent !== null) {
    // Colour and layout priority are separate judgements. A filling context is
    // worth a warning colour long before it is worth taking a narrow line's
    // space away from the workflow — only a nearly exhausted one is urgent
    // enough to outrank the tier it would normally be filtered out by.
    const exhausted = input.contextPercent >= CONTEXT_CRITICAL_PERCENT;
    segments.push({
      slot: Slot.context,
      priority: exhausted ? Priority.exhaustedContext : Priority.context,
      text: `ctx ${Math.round(input.contextPercent)}%`,
      tone: exhausted
        ? "error"
        : input.contextPercent >= CONTEXT_WARNING_PERCENT
          ? "warning"
          : "muted",
      critical: exhausted,
    });
  }

  const verification = verificationState(input);
  if (verification !== null) {
    const attention = verificationNeedsAttention(verification);
    segments.push({
      slot: Slot.verification,
      priority: attention
        ? Priority.failedVerification
        : Priority.verification,
      text: `${verification === "verified" ? "✓" : attention ? "⚠" : ""} ${verification}`.trim(),
      tone: verificationTone(verification),
      critical: attention,
    });
  }

  const lsp = lspState(input);
  if (lspNeedsAttention(lsp)) {
    segments.push({
      slot: Slot.risk,
      priority: Priority.lsp,
      text: `⚠ LSP ${lsp}`,
      tone: "error",
      critical: true,
    });
  }

  if (input.state.permissions.level === "yolo") {
    segments.push({
      slot: Slot.risk,
      priority: Priority.yolo,
      text: "⚠ YOLO",
      tone: "error",
      bold: true,
      critical: true,
    });
  }

  return segments;
}

/**
 * Terminal cells, not JavaScript characters. `⚠`, `✓`, CJK and emoji all cost
 * more cells than they do string length, and a selection that measured length
 * would believe a line fits and then have to truncate a finished segment at
 * the edge — the one thing this layout exists to avoid.
 */
function widthOf(segments: readonly Segment[]): number {
  if (segments.length === 0) return 0;
  return (
    segments.reduce((total, segment) => total + visibleWidth(segment.text), 0) +
    visibleWidth(STATUS_SEPARATOR) * (segments.length - 1)
  );
}

/**
 * Keep what the width tier allows plus everything critical, then, while the
 * result is still too wide, drop the least important segment that is left.
 * Segments give up their place entirely rather than being shaved at the edge,
 * so whatever remains stays readable — and the survivors are then put back
 * into reading order, which is not the order they were dropped in.
 */
function selectFooterSegments(
  segments: readonly Segment[],
  width: number,
): Segment[] {
  const allowed = ROUTINE_TIERS[footerTier(width)];
  const kept = segments.filter(
    (segment) => segment.critical || allowed.has(segment.slot),
  );
  while (kept.length > 1 && widthOf(kept) > width) {
    let victim = 0;
    for (let index = 1; index < kept.length; index += 1)
      if (kept[index]!.priority > kept[victim]!.priority) victim = index;
    kept.splice(victim, 1);
  }
  return kept.sort((a, b) => a.slot - b.slot);
}

export function renderFooterLines(
  theme: Theme,
  width: number,
  input: FooterInput,
): string[] {
  const available = Math.max(1, width);
  const selected = selectFooterSegments(
    collectSegments(input, available),
    available,
  );
  const line = selected
    .map((segment) =>
      renderSegment(theme, segment.text, {
        tone: segment.tone,
        bold: segment.bold,
      }),
    )
    .join(statusSeparator(theme));
  return [visibleWidth(line) > available ? crop(line, available) : line];
}

/**
 * The single definition of the terminal size classes every Pi surface uses.
 *
 * Before this module there were two: the menu shell switched at 52/90 columns
 * (counting rows as well), the Aurora chrome at 76/124 (columns only). Two
 * surfaces therefore disagreed about what "narrow" meant, and neither boundary
 * was stated anywhere a third surface could find it.
 *
 * This file deliberately imports nothing. `menu-ui.ts` notes that a static
 * `pi-tui` import breaks the jiti test loader, and every menu module reaches
 * these thresholds — keeping the size math dependency-free means importing it
 * can never pull a renderer into a module that must stay loadable.
 */

/**
 * A — compact: single-line entries, no descriptions, no detail area.
 * B — standard: one description line per entry.
 * C — comfortable: two description lines plus a detail area.
 * D — wide: room for the optional extras; no surface may claim it permanently.
 */
export type Layout = "compact" | "standard" | "comfortable" | "wide";

export const LAYOUT_COLUMNS = {
  standard: 52,
  comfortable: 90,
  wide: 120,
} as const;

export const LAYOUT_ROWS = {
  standard: 14,
  comfortable: 28,
  wide: 30,
} as const;

/** Below this width an overlay gives up its outer margin to gain content. */
const TIGHT_MARGIN_COLUMNS = 36;

/**
 * The size class of a full terminal. Both dimensions must clear a threshold:
 * a 200×10 terminal is compact, because height is what the entry lists and
 * detail areas actually spend.
 */
export function layoutForSize(columns: number, rows: number): Layout {
  if (columns < LAYOUT_COLUMNS.standard || rows < LAYOUT_ROWS.standard)
    return "compact";
  if (columns >= LAYOUT_COLUMNS.wide && rows >= LAYOUT_ROWS.wide) return "wide";
  if (
    columns >= LAYOUT_COLUMNS.comfortable &&
    rows >= LAYOUT_ROWS.comfortable
  )
    return "comfortable";
  return "standard";
}

/**
 * The size class of a single-line surface. The footer occupies one row at any
 * height, so only its width can decide how much it may say.
 */
export function footerTier(columns: number): Layout {
  if (columns < LAYOUT_COLUMNS.standard) return "compact";
  if (columns >= LAYOUT_COLUMNS.wide) return "wide";
  if (columns >= LAYOUT_COLUMNS.comfortable) return "comfortable";
  return "standard";
}

/** The outer gap an overlay leaves on every side of the terminal. */
export function overlayMargin(columns: number, rows: number): 1 | 2 {
  return columns < TIGHT_MARGIN_COLUMNS || rows < LAYOUT_ROWS.standard ? 1 : 2;
}

> pi can create extensions. Ask it to build one for your use case.

# Extensions

Extensions are TypeScript modules that extend pi's behavior. They can subscribe to lifecycle events, register custom tools callable by the LLM, add commands, and more.

> **Placement for /reload:** Put extensions in `~/.pi/agent/extensions/` (global) or `.pi/extensions/` (project-local) for auto-discovery. Use `pi -e ./path.ts` only for quick tests. Extensions in auto-discovered locations can be hot-reloaded with `/reload`.

**Key capabilities:**
- **Custom tools** - Register tools the LLM can call via `pi.registerTool()`
- **Event interception** - Block or modify tool calls, inject context, customize compaction
- **User interaction** - Prompt users via `ctx.ui` (select, confirm, input, notify)
- **Custom UI components** - Full TUI components with keyboard input via `ctx.ui.custom()` for complex interactions
- **Custom commands** - Register commands like `/mycommand` via `pi.registerCommand()`
- **Session persistence** - Store state that survives restarts via `pi.appendEntry()`
- **Custom rendering** - Control how tool calls/results and messages appear in TUI

**Example use cases:**
- Permission gates (confirm before `rm -rf`, `sudo`, etc.)
- Git checkpointing (stash at each turn, restore on branch)
- Path protection (block writes to `.env`, `node_modules/`)
- Custom compaction (summarize conversation your way)
- Conversation summaries (see `summarize.ts` example)
- Interactive tools (questions, wizards, custom dialogs)
- Stateful tools (todo lists, connection pools)
- External integrations (file watchers, webhooks, CI triggers)
- Games while you wait (see `snake.ts` example)

See [examples/extensions/](../examples/extensions/) for working implementations.

