  };

  function buildConfig(ctx: ExtensionContext): LspConfig {
    const cliMode = parseMode(pi.getFlag("lsp-mode"));
    const trusted = ctx.isProjectTrusted();
    const loadedSetup = loadSetupConfig(ctx.cwd, trusted);
    for (const diagnostic of loadedSetup.diagnostics) {
      logger(
        diagnostic.level === "error" ? "error" : "info",
        `${diagnostic.source}: ${diagnostic.message}`,
      );
    }
    const projectConfig = trusted
      ? readProjectConfig(ctx.cwd, logger)
      : undefined;
    const layers = {
      defaults: defaultConfig(),
      global: loadedSetup.config.lsp,
      trusted,
      projectRoot: ctx.cwd,
      sessionFlags: {
        ...(cliMode ? { mode: cliMode } : {}),
        ...sessionOverride,
      },
    };
    try {
      return resolveConfig({ ...layers, projectConfig });
    } catch (error) {
      // resolveConfig rejects a project profile it will not run — a malformed
      // value or a command outside the allowed set. readProjectConfig only
      // guards the JSON parse, so without this the throw would take
      // session_start down: a broken .pi/lsp.json would become a denial of
      // service. Drop the project layer entirely and keep going on the
      // defaults; the reason stays in the log for `/lsp log`.
      logger(
        "error",
        `.pi/lsp.json was ignored: ${error instanceof Error ? error.message : String(error)}`,
      );
      return resolveConfig(layers);
    }
  }

  function auroraLspState(): NonNullable<AuroraUiStatePatch["lsp"]> {
    const servers = registry?.list() ?? [];
    return {
      state: registry ? computeLspStatus(config, servers) : "aus",
      detail:
        servers.length > 0
          ? `${servers.length} Server${servers.length === 1 ? "" : "s"}`
          : undefined,
    };
  }

  function refreshStatus(ctx: ExtensionContext): void {
    if (!registry) {
      publishLspStatus(ctx, undefined);
    } else {
      publishLspStatus(ctx, computeLspStatus(config, registry.list()));
    }
    if (auroraEpoch) {
      publishAuroraUiPatch(pi, auroraEpoch, "lsp", {
        lsp: auroraLspState(),
      });
    }
  }

  function subscribeAuroraProvider(): void {
    unsubscribeAurora?.();
    unsubscribeAurora = pi.events.on(AURORA_UI_CHANNELS.request, (value) => {
      if (!isAuroraUiStateRequest(value)) return;
      auroraEpoch = value.sessionEpoch;
      publishAuroraUiSnapshot(pi, value, "lsp", {
        lsp: auroraLspState(),
      });
    });
  }

  const deps: LspToolsDeps = {
    getConfig: () => config,
    getRegistry: () => {
      if (!registry) registry = new ServerRegistry({ config, logger });
      return registry;
    },
    logger,
  };

  function captureControlCenterSession(ctx: ExtensionContext): unknown {
    return {
      epoch: sessionEpoch,
      sessionId: ctx.sessionManager.getSessionId(),
    };
  }

  function isCurrentControlCenterSession(
    ctx: ExtensionContext,
    token: unknown,
  ): boolean {
    if (!token || typeof token !== "object") return false;
    const state = token as { epoch?: unknown; sessionId?: unknown };
    return (
      state.epoch === sessionEpoch &&
      state.sessionId === activeSessionId &&
      ctx.sessionManager.getSessionId() === activeSessionId
    );
  }

  function captureControlCenterDeps(): LspToolsDeps {
    const capturedConfig = config;
    const capturedRegistry =
      registry ??
      new ServerRegistry({
        config: capturedConfig,
        logger,
      });
    return {
      getConfig: () => capturedConfig,
      getRegistry: () => capturedRegistry,
      logger,
    };
  }

  pi.registerFlag("lsp-mode", {
    description: "LSP-Aktivierungsmodus: off | auto | force",
    type: "string",
  });
  pi.registerFlag("lsp-log", {
    description: "LSP-Log-Ausführlichkeit: off | error | info | trace",
    type: "string",
  });

  registerLspDiagnosticsTool(pi, deps);
  registerLspNavigationTools(pi, deps);
  const openLspDiagnostics = registerLspControlCenter(pi, {
    getStatus: () =>
      registry ? computeLspStatus(config, registry.list()) : "aus",
    refreshStatus,
    captureSession: captureControlCenterSession,
    isSessionCurrent: isCurrentControlCenterSession,
    captureDeps: captureControlCenterDeps,
  });

  pi.on("session_start", async (_event, ctx) => {
    const previousRegistry = registry;
    sessionEpoch += 1;
    activeSessionId = ctx.sessionManager.getSessionId();
    registry = undefined;
    await previousRegistry?.shutdownAll();
    sessionOverride = {};
    auroraEpoch = undefined;
    subscribeAuroraProvider();
    config = buildConfig(ctx);
    registry = new ServerRegistry({ config, logger });
    refreshStatus(ctx);
  });

  pi.on("session_shutdown", async (_event, ctx) => {
    const previousRegistry = registry;
    sessionEpoch += 1;
    activeSessionId = undefined;
    registry = undefined;
    await previousRegistry?.shutdownAll();
    sessionOverride = {};
    unsubscribeAurora?.();
    unsubscribeAurora = undefined;
    publishLspStatus(ctx, undefined);
